package com.benhsoan.domain.medicalrecord; import static org.junit.jupiter.api.Assertions.*; import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test; import com.benhsoan.domain.shared.exception.ValidationException;
class MedicalRecordTest { @Test void locksAndRejectsFurtherUpdates(){MedicalRecord r=MedicalRecord.create(UUID.randomUUID(),null,null,null,null,null,null,null,null,UUID.randomUUID());Instant now=Instant.now();r.open(UUID.randomUUID(),now);r.lock(UUID.randomUUID(),now);assertTrue(r.isLocked());assertThrows(ValidationException.class,()->r.updateContent(null,null,null,null,null,null,null,null,UUID.randomUUID(),now));}}
